script:
let sigs = [
  ["xposedbridge", "XposedBridge Marker", "HIGH", "XposedBridge API reference — Java-layer hooking framework"],
  ["de.robv.android.xposed", "Xposed Namespace", "HIGH", "Xposed framework package namespace (de.robv.android.xposed)"],
  ["lsposed", "LSPosed Marker", "HIGH", "LSPosed — modern Xposed implementation via Zygisk"],
  ["edxposed", "EdXposed Marker", "HIGH", "EdXposed — Xposed implementation via Riru"],
  ["virtualxposed", "VirtualXposed Marker", "HIGH", "VirtualXposed — runs the app in a virtual container with Xposed enabled"],
  ["zygisk", "Zygisk Marker", "HIGH", "Zygisk injection reference — Magisk's Zygote injection mechanism"],
  ["riru", "Riru Marker", "HIGH", "Riru — Zygote injection library that hosts hook modules"],
  ["substrate", "Substrate Marker", "HIGH", "Cydia Substrate — mobile hooking framework"],
  ["saurik", "Substrate Author Marker", "MEDIUM", "saurik (Jay Freeman) reference — associated with Substrate"],
  ["sandhook", "SandHook Marker", "HIGH", "SandHook — ART native/Java hooking framework"],
  ["dobby", "Dobby Hook Engine", "MEDIUM", "Dobby — cross-platform native inline hook engine"],
  ["hookzz", "HookZz Engine", "MEDIUM", "HookZz — native inline hooking engine"],
  ["shadowhook", "ShadowHook Marker", "MEDIUM", "ShadowHook (ByteDance) — native inline hook library"],
  ["taichi", "TaiChi Marker", "MEDIUM", "TaiChi — Xposed-like hook framework (also a common word; review hits in context)"]
];
for sig in sigs {
  let hits = find_strings(sig[0]);
  for h in hits {
    report(sig[1], h.address, sig[2], h.value + " (" + sig[3] + ")");
  }
}
